'use strict';
const paths={spark:'M12 3 14.8 9.2 21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8Z',home:'m3 10 9-7 9 7v10H3Zm6 10v-7h6v7',plus:'M12 5v14M5 12h14',minus:'M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',fire:'M12 3c0 5-6 6-6 12a6 6 0 0 0 12 0c0-2-1-4-3-6 0 3-2 4-3 4 2-4 2-7 0-10Z',water:'M12 3C9 8 5 11 5 15a7 7 0 0 0 14 0c0-4-4-7-7-12ZM8 15a4 4 0 0 0 4 4',camera:'M8 6 9 3h6l1 3h5v14H3V6Zm8 7a4 4 0 1 0-8 0 4 4 0 0 0 8 0',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M7 12h10',search:'M16 16 21 21M18 10A8 8 0 1 1 2 10a8 8 0 0 1 16 0',chart:'M4 20V11m5 9V6m6 14V9m5 11V3',trophy:'M7 3h10v8a5 5 0 0 1-10 0ZM7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 4v5m-4 0h8',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',bell:'M5 17h14l-2-3V9A5 5 0 0 0 7 9v5Zm5 3h4M12 2v2',calendar:'M3 5h18v16H3ZM7 3v4m10-4v4M3 10h18',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',leaf:'M20 3C6 2 2 8 5 15s15 5 15-12ZM5 19 16 8',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z',food:'M5 3v6m3-6v6M2 3v6a3 3 0 0 0 6 0M5 12v9M17 3v18m0-18c-4 3-4 9 0 9',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-4 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0m-3 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0',bolt:'m13 2-9 12h7l-1 8 10-13h-8Z',settings:'M9 3h6l1 4 4 2v6l-4 2-1 4H9l-1-4-4-2V9l4-2Zm6 9a3 3 0 1 0-6 0 3 3 0 0 0 6 0',logout:'M9 3H3v18h6m-1-9h13m-5-5 5 5-5 5',lock:'M5 10h14v11H5Zm3 0V7a4 4 0 0 1 8 0v3m-4 5v2',edit:'m4 16-1 5 5-1L21 7l-4-4Zm10-10 4 4',heart:'M12 20S2 14 2 8c0-6 8-6 10-1 2-5 10-5 10 1 0 6-10 12-10 12Z',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4h.01',signal:'M3 20v-3m5 3v-7m5 7V9m5 11V5',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',refresh:'M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 14-2m0 10a8 8 0 0 1-14 2',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-9-1v6m0-10v.01',trash:'M3 6h18M5 6l1 15h12l1-15M9 6V3h6v3m-5 4v7m4-7v7',book:'M3 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3Zm18 0h-6a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h5Z',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6Zm-5 10 3 3 7-7',upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',dumbbell:'M6 6v12m12-12v12M3 8v8m18-8v8M6 12h12'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups=[['Everyday',['home','diary','nutrition','water','history']],['Food & discovery',['log','search','food','manual','camera','scanning','review','logged']],['Play & progress',['quests','journey','collection','reward','streak']],['Getting started',['welcome','login','register','reset','about','goal','targets','ready']],['You & preferences',['profile','editProfile','editGoals','settings','notifications']],['Edge states',['empty','loading','offline','scanError']]];
const names={home:'Today',diary:'Food diary',nutrition:'Nutrition detail',water:'Hydration',history:'Progress',log:'Add a meal',search:'Food search',food:'Food & portion',manual:'Custom food',camera:'Photo capture',scanning:'Analyzing photo',review:'Review AI estimate',logged:'Meal logged',quests:'Daily quests',journey:'Level journey',collection:'Badge collection',reward:'Reward unlocked',streak:'Your streak',welcome:'Welcome',login:'Sign in',register:'Create account',reset:'Password recovery',about:'Your profile',goal:'Choose a goal',targets:'Daily targets',ready:'Your plan is ready',profile:'Your space',editProfile:'Edit profile',editGoals:'Edit goals',settings:'Preferences',notifications:'Notifications',empty:'First-day empty state',loading:'Loading state',offline:'Offline state',scanError:'Scan needs help'};
const ids=groups.flatMap(g=>g[1]);
const newScreens=new Set(['quests','journey','collection','reward','welcome','reset','settings','notifications']);
const navScreens=new Set(['home','diary','nutrition','water','history','quests','journey','collection','streak','profile','empty','loading','offline']);
const state={entries:[],lastEntry:null,lastXp:0,rewardedMeals:[],hydrationRewarded:false,screen:'home',mode:'prototype',filter:'all',water:1250,waterGoal:2000,portion:1,meal:'Lunch',foodTab:'Recent',goal:'Build muscle',activity:'Moderately active',height:165,weight:62,birthday:'1998-06-12',sex:'Female',name:'Neha',calories:2100,protein:130,carbs:260,fat:60,logged:false,deleted:false,xp:740,claimed:false,query:'',historyRange:'Week',selectedDay:21,selectedFood:'Harvest chicken bowl',notifications:{meals:true,water:true,quests:true,haptics:true},custom:null};
const btn=(label,to,kind='',ic='')=>`<button type="button" class="btn ${kind}" data-go="${to}">${ic?icon(ic):''}${label}</button>`;
const actionBtn=(label,action,kind='',ic='')=>`<button type="button" class="btn ${kind}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
const chip=(label,ic='',cls='')=>`<span class="chip ${cls}">${ic?icon(ic):''}${label}</span>`;
const progress=(value,color='')=>`<div class="progress"><span style="width:${Math.min(value,100)}%;${color?'background:'+color:''}"></span></div>`;
const header=(title,back='home',right='')=>`<div class="backbar"><button class="round-btn" data-go="${back}" aria-label="Back to ${names[back]}">${icon('back')}</button><h3>${title}</h3>${right||'<span style="width:34px"></span>'}</div>`;
const field=(label,name,value='',type='text',placeholder='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" placeholder="${placeholder}" ${type==='number'?'min="0" step="any"':''} required></label>`;
const select=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select></label>`;
const steps=n=>`<div class="steps">${[1,2,3].map(i=>`<span class="${i<=n?'active':''}"></span>`).join('')}</div>`;
const art=(name,cls,alt)=>`<img src="assets/${name}.png" class="${cls}" alt="${alt}" loading="lazy">`;
const foodRow=(name,detail,cal,ic='food',to='food',photo=false)=>`<button class="meal-row" data-go="${to}" ${to==='food'?`data-food="${esc(name)}"`:''}>${photo?art('meal-bowl','meal-thumb','Chicken, quinoa and avocado bowl'):`<span class="meal-symbol">${icon(ic)}</span>`}<span><h3>${name}</h3><p class="small muted">${detail}</p></span><span class="end">${cal}<p class="small muted">${cal==='+'?'':'kcal'}</p></span></button>`;
const macros=(p=86+state.entries.reduce((s,e)=>s+(e.nutrients[0]||0),0),c=148+state.entries.reduce((s,e)=>s+(e.nutrients[1]||0),0),f=42+state.entries.reduce((s,e)=>s+(e.nutrients[2]||0),0))=>`<div class="three mt12">${[['Protein',p,state.protein,'orange'],['Carbs',c,state.carbs,'purple'],['Fat',f,state.fat,'blue']].map(([label,n,total,color])=>`<button class="macro ${color}" data-go="nutrition" style="text-align:left;border:0"><span><i class="macro-dot"></i>${label}</span><strong>${n}<small> / ${total} g</small></strong>${progress(n/total*100,'var(--'+color+')')}</button>`).join('')}</div>`;
function dayEnergy(){return (state.deleted?726:1284)+state.entries.reduce((sum,e)=>sum+e.calories,0);}
function addEntry(name,calories,meal,nutrients=[]){state.lastXp=state.rewardedMeals.includes(meal)?0:25;if(state.lastXp)state.rewardedMeals.push(meal);state.xp+=state.lastXp;const entry={name,calories,meal,portion:state.portion,nutrients};state.entries.push(entry);state.lastEntry=entry;state.logged=true;go('logged');}
function energy(){const consumed=dayEnergy();return `<div class="energy-card"><div class="energy-head"><span>Today's energy</span><button class="text-btn" data-go="editGoals" aria-label="Edit daily energy target">${icon('target')}</button></div><div class="energy-body"><div class="cal-ring"><svg viewBox="0 0 140 140" aria-hidden="true"><circle class="ring-track" cx="70" cy="70" r="60"/><circle class="ring-value" cx="70" cy="70" r="60" style="stroke-dashoffset:${377*(1-Math.min(consumed/state.calories,1))}"/></svg><div class="ring-label"><strong>${Math.max(0,state.calories-consumed).toLocaleString()}</strong><span>kcal remaining</span></div></div><div class="energy-side"><div><span>Eaten</span><strong>${consumed.toLocaleString()}</strong><small>kcal</small></div><div><span>Daily target</span><strong>${state.calories.toLocaleString()}</strong><small>kcal</small></div></div></div><div class="energy-foot">${icon('leaf')} Room for good food. Fuel your evening.</div></div>`;}
function home(){return `<div class="row between greeting"><div><div class="eyebrow">MONDAY, SEPTEMBER 21</div><h1>Hey, ${esc(state.name)} <span class="lime">✳</span></h1></div><div class="row gap6"><button class="round-btn" data-go="notifications" aria-label="Notifications">${icon('bell')}</button><button class="avatar-btn" data-go="profile" aria-label="Open your profile"><span class="avatar">${esc(state.name[0]||'N')}</span></button></div></div><div class="week-strip">${['T','W','T','F','S','S','M'].map((d,i)=>`<button class="day ${state.selectedDay===i+15?'active':''}" data-day="${i+15}">${d}<strong>${i+15}</strong><i></i></button>`).join('')}</div>${energy()}${macros()}<button class="streak-card mt16" data-go="streak"><div><div class="eyebrow">SMALL WINS. BIG ENERGY.</div><h3>You're on a 7-day roll.</h3><p>Ember likes your consistency.</p></div>${art('ember','art','Ember, your orange flame companion')}</button><div class="xp-track">${icon('spark')}<strong>Level 4</strong>${progress(state.xp/1000*100)}${state.xp} / 1,000 XP</div><div class="section-head" style="margin-top:15px"><h3>On your plate</h3><button class="text-btn" data-go="diary">View diary ${icon('chevron')}</button></div>${foodRow('Breakfast','Overnight oats · 8:30 AM','426','sun','diary')}${foodRow('Lunch','Harvest bowl · 1:15 PM','558','food','diary',true)}<div class="water-mini mt16">${icon('water')}<button class="text-btn" data-go="water" style="text-align:left;color:inherit;flex:1"><h3 style="font-size:13px">${(state.water/1000).toFixed(2)} / ${(state.waterGoal/1000).toFixed(1)} L</h3><p>A little sip goes a long way.</p></button><button class="round-btn" data-action="water" aria-label="Add 250 milliliters of water">${icon('plus')}</button></div><div class="section-head"><h3>Your next little win</h3><button class="text-btn" data-go="quests">Quests ${icon('chevron')}</button></div><div class="quest-card"><span class="quest-icon">${icon('book')}</span><div class="quest-body"><h3>Make a little meal memory</h3><p>Log your next meal today.</p>${progress(state.logged?100:66)}</div>${chip('+25 XP')}</div>`;}
const screens={home};
function nav(screen){let active=['home','diary','nutrition','water','streak','empty','loading','offline'].includes(screen)?'home':['quests','journey','collection'].includes(screen)?'quests':screen;return `<nav class="bottom-nav" aria-label="App navigation">${[['home','home','Today'],['history','chart','Progress'],['log','plus',''],['quests','spark','Quests'],['profile','user','You']].map(([id,ic,label])=>`<button data-go="${id}" class="${active===id?'active':''} ${id==='log'?'add-tab':''}" aria-label="${label||'Add food'}">${icon(ic)}${label?`<span>${label}</span>`:''}</button>`).join('')}</nav>`;}
function phone(screen){return `<div class="phone ${navScreens.has(screen)?'has-nav':''}" data-screen="${screen}"><div class="statusbar"><span>9:41</span><span class="island"></span><span class="status-icons">${icon('signal')}${icon('wifi')}<i class="battery"></i></span></div><div class="phone-scroll">${screens[screen]()}</div>${navScreens.has(screen)?nav(screen):''}<div class="home-indicator"></div></div>`;}
const descriptions={home:['A little better.\nEvery day.','A calm overview of your nutrition, with a little spark of encouragement. The most important numbers come first.','Tap the energy target, a macro, the streak card, or a day. Add water with one tap.','Calories and XP stay visually separate. The reward is for showing up.'],log:['Less friction.\nMore living.','Three ways to log: take a photo, search familiar foods, or enter a custom meal.','Try the photo flow, or search the food library.','Review every AI estimate before it enters your diary.'],quests:['Small wins.\nReal momentum.','Optional daily quests reward recording meals, checking in, and building a sustainable routine.','Claim a completed quest, then explore your level journey.','No rewards for eating less. No competitive weight-loss leaderboard.'],welcome:['Meet your\nlittle spark.','Ember gives FitLens a recognizable, warm personality. Onboarding introduces the value before asking for details.','Walk through sign-up, profile, goal, and target review.','Three focused setup steps with an editable plan at the end.'],review:['You have the\nfinal say.','Photo recognition feels useful without pretending an estimate is a fact. Every portion remains editable.','Adjust the serving, pick a meal, and add it to the diary.','The scan flow is simulated. It does not upload a photo.'],history:['See the habit.\nFeel the progress.','A clear weekly view pairs food history with consistency, leaving judgment out of the conversation.','Switch the time range and open a day in the diary.','Targets guide the chart. They are not a pass/fail score.'],profile:['Your pace.\nYour space.','Personal targets, preferences, and achievements live together in one quiet corner.','Edit your profile and targets, or explore notification preferences.','Sample profile data stays inside this prototype session.']};
function note(screen){const group=groups.find(g=>g[1].includes(screen))[0];const d=descriptions[screen]||[names[screen]+'.\nThoughtfully considered.',group==='Edge states'?'The experience stays clear when things are new, slow, or don’t go to plan.':'A complete part of the FitLens journey, using the same type, spacing, color, and interaction language.','Buttons, fields, tabs, and navigation are connected. Explore the next step directly from the phone.',newScreens.has(screen)?'Proposed feature for the redesign. It will need product logic during implementation.':'Reworks a flow from the existing app with clearer hierarchy and fewer distractions.'];return `<aside class="notes"><div class="eyebrow">${group} / ${String(ids.indexOf(screen)+1).padStart(2,'0')}</div><h1>${d[0].replace('\n','<br>')}</h1><p>${d[1]}</p><span class="note-tag">${newScreens.has(screen)?'NEW EXPERIENCE':'REDESIGNED FLOW'}</span><div class="note-line"></div><div class="note-row">${icon('target')}<div><h3>Try it</h3>${d[2]}</div></div><div class="note-row">${icon('heart')}<div><h3>Design intention</h3>${d[3]}</div></div><div class="note-line"></div><small>INTERACTIVE DESIGN PROTOTYPE<br>Sample data · simulated AI & account flows<br>390 px mobile reference · September 2026</small></aside>`;}
function render(){document.getElementById('studio').innerHTML=`<header class="studio-header"><div class="brand"><span class="brand-mark">${icon('spark')}</span>FitLens <small>Design studio</small></div><nav class="studio-tabs" aria-label="Review modes">${[['prototype','Prototype'],['gallery','All screens'],['system','Design system']].map(([id,label])=>`<button data-mode="${id}" class="${state.mode===id?'active':''}">${label}</button>`).join('')}</nav><div class="studio-meta"><span>CONCEPT 01 / 2026</span><button class="outline-btn" data-action="resetDemo">Reset demo</button></div></header><div class="workspace"><aside class="sidebar"><div class="sidebar-top">${ids.length} screens. One cohesive journey.</div>${groups.map(([label,list])=>`<div class="eyebrow">${label}</div>${list.map(id=>`<button data-go="${id}" class="${state.screen===id&&state.mode==='prototype'?'active':''}"><span class="num">${String(ids.indexOf(id)+1).padStart(2,'0')}</span>${names[id]}${newScreens.has(id)?'<span class="new">NEW</span>':''}</button>`).join('')}`).join('')}</aside><main class="stage">${state.mode==='prototype'?`<div class="stage-top"><div class="breadcrumbs">FitLens / <strong>${names[state.screen]}</strong></div><select class="screen-select-mobile" aria-label="Choose a screen" id="screenSelect">${groups.map(([label,list])=>`<optgroup label="${label}">${list.map(id=>`<option value="${id}" ${id===state.screen?'selected':''}>${names[id]}</option>`).join('')}</optgroup>`).join('')}</select><div class="stage-tools"><button class="tool" data-action="prevScreen" aria-label="Previous screen">${icon('back')}</button><button class="tool" data-action="nextScreen" aria-label="Next screen">${icon('arrow')}</button></div></div><div class="prototype-layout"><div class="phone-wrap"><div class="phone-label"><span>${String(ids.indexOf(state.screen)+1).padStart(2,'0')} — ${names[state.screen].toUpperCase()}</span><span>LIVE PROTOTYPE</span></div><div class="phone-shell">${phone(state.screen)}</div><div class="demo-label">Tap around. Everything here is a design preview.</div></div>${note(state.screen)}</div>`:state.mode==='gallery'?gallery():designSystem()}<div class="studio-footer">FitLens · Product redesign by Neha & you · Review the experience before building it.</div></main></div>`;}
function go(id){if(!ids.includes(id))return;state.screen=id;state.mode='prototype';history.replaceState(null,'','#'+id);render();}
let toastTimer;function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400);}
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-open-screen]');if(!target)return;if(target.dataset.go){if(target.dataset.food){state.selectedFood=target.dataset.food;state.portion=1;}if(target.dataset.go==='camera'||target.dataset.go==='review'||target.dataset.go==='scanning')state.selectedFood='Harvest chicken bowl';go(target.dataset.go);}else if(target.dataset.mode){state.mode=target.dataset.mode;render();}else if(target.dataset.openScreen)go(target.dataset.openScreen);else if(target.dataset.action)handleAction(target.dataset.action,target);else if(target.dataset.day){state.selectedDay=Number(target.dataset.day);go('diary');}else if(target.dataset.choice){state[target.dataset.choice]=target.dataset.value;render();}});
document.addEventListener('change',e=>{if(e.target.id==='screenSelect')go(e.target.value);if(e.target.id==='galleryFilter'){state.filter=e.target.value;render();}});
document.addEventListener('submit',e=>{if(e.target.dataset.form){e.preventDefault();handleForm(e.target.dataset.form,new FormData(e.target));}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.sheet-overlay')?.remove();});
function gallery(){const list=state.filter==='all'?ids:groups.find(g=>g[0]===state.filter)[1];return `<div class="gallery-head"><div><h1>The whole experience.</h1><p>${ids.length} screens, from the very first hello to the little wins along the way.</p></div><select id="galleryFilter" class="gallery-filter" aria-label="Filter screens"><option value="all">All journeys (${ids.length})</option>${groups.map(([name,list])=>`<option ${name===state.filter?'selected':''}>${name}</option>`).join('')}</select></div><div class="gallery">${list.map(id=>`<article class="gallery-item"><div class="gallery-caption">${names[id]}<span>${String(ids.indexOf(id)+1).padStart(2,'0')}</span></div><div class="gallery-device" data-open-screen="${id}" role="button" tabindex="0" aria-label="Open ${names[id]}">${phone(id)}</div></article>`).join('')}</div>`;}
function designSystem(){return `<div class="gallery-head"><div><h1>A system with a little spark.</h1><p>The visual and behavioral foundation for the FitLens rebuild.</p></div><span class="note-tag">DESIGN REFERENCE / V1</span></div><div class="system-grid"><section class="system-card"><h2>01 / Color</h2><div class="swatches">${[['Ink','#101211'],['Surface','#1b1e1b'],['Volt','#d1fa70'],['Ember','#ff9f68'],['Water','#8ecfea'],['Carbs','#c4b4f9']].map(([n,c])=>`<div class="swatch"><i style="background:${c}"></i><b>${n}</b><span>${c}</span></div>`).join('')}</div><p>Ink creates focus. Volt marks the next action. Orange, lilac, and blue keep nutrients recognizable without relying on color alone.</p></section><section class="system-card"><h2>02 / Typography</h2><div class="type-example">Small steps.<br>Big energy.</div><div class="token-line"><span>Manrope / 750–800</span><span>Titles · numerals</span></div><div class="token-line"><span>DM Sans / 400–700</span><span>Body · controls</span></div><p>Expressive, compact headings. Clear labels. Tabular numbers for changing nutrition values.</p></section><section class="system-card system-wide"><h2>03 / The asset family</h2><div class="asset-gallery">${art('ember','','Ember, the flame companion')}${art('meal-bowl','','Editorial meal imagery')}${art('achievement','','Collectible achievement token')}</div><p>Ember brings warmth to consistency. Food imagery supports logging and review. A dimensional token makes achievement feel tangible. Original assets generated for this concept; meal imagery is illustrative.</p></section><section class="system-card"><h2>04 / Shape & rhythm</h2><div class="token-line"><span>Spacing</span><span>4 · 8 · 12 · 16 · 24 · 32</span></div><div class="token-line"><span>Corner radius</span><span>12 controls · 20 cards · 28 sheets</span></div><div class="token-line"><span>Primary actions</span><span>49 px minimum height</span></div><div class="token-line"><span>Mobile reference</span><span>390 × 844 px</span></div><p>Generous main actions, contained sections, and an anchored five-item navigation. Content scrolls independently of navigation.</p></section><section class="system-card"><h2>05 / Motion & feel</h2><ul class="spec-list"><li>Press: 120 ms, 0.98 scale, light haptic.</li><li>Sheets: 280 ms ease-out; dismiss with back or close.</li><li>Progress: 400 ms on meaningful state change.</li><li>Reward: one 600 ms moment; no endless confetti.</li><li>Respect reduced-motion and haptic preferences.</li></ul><p>Motion is an implementation reference. This mockup uses lightweight press, progress, and scanning transitions.</p></section><section class="system-card"><h2>06 / Gamification rules</h2><ul class="spec-list"><li>Meal logging: +25 XP once per meal slot per day.</li><li>Daily check-in: +10 XP once a day.</li><li>Hydration check-in: +15 XP once a day, independent of amount.</li><li>Level progress reflects total XP; no points deducted.</li><li>Streaks reward a check-in, never calorie restriction.</li><li>Badges are private, collectible milestones.</li></ul></section><section class="system-card"><h2>07 / States & accessibility</h2><ul class="spec-list"><li>Empty: one clear invitation to start.</li><li>Loading: stable skeletons, no fake values.</li><li>Offline: acknowledge saved data and offer retry.</li><li>AI uncertainty: editable estimates, manual alternative.</li><li>Labels accompany color; keyboard focus stays visible.</li><li>Production pass: VoiceOver, larger text, contrast and touch targets.</li></ul></section><section class="system-card system-wide"><h2>08 / Connected journeys</h2><div class="flow-map">${['Welcome','Create account','Your profile','Choose a goal','Review targets','Today'].map(n=>`<span>${n}</span>`).join(' → ')}</div><div class="flow-map mt16">${['Add a meal','Capture photo','Analyze','Review estimate','Adjust portion','Log meal','Daily quest'].map(n=>`<span>${n}</span>`).join(' → ')}</div><p>This is a design prototype. Account creation, AI recognition, persistence, notifications, and nutrition calculations are simulated. Sample targets demonstrate layout and are not calculated recommendations. The existing mobile and backend code remain the implementation foundation.</p></section></div>`;}
function handleAction(action,target){if(action==='badge'){sheet(esc(target.dataset.badge),target.dataset.locked==='true'?'Keep building your rhythm. Unlock this badge when you '+target.dataset.description.toLowerCase()+'.':'A little milestone to keep. '+target.dataset.description+'.',art('achievement','success-art','Collectible badge')+(target.dataset.locked==='true'?btn('View my journey','journey'):actionBtn('Back to my collection','closeSheet')));}else if(action==='water'){state.water+=250;if(!state.hydrationRewarded){state.xp+=15;state.hydrationRewarded=true;}render();toast('250 ml added. Nice little check-in.');}else if(action==='resetDemo'){Object.assign(state,{entries:[],lastEntry:null,lastXp:0,rewardedMeals:[],hydrationRewarded:false,screen:'home',mode:'prototype',water:1250,waterGoal:2000,portion:1,meal:'Lunch',foodTab:'Recent',goal:'Build muscle',activity:'Moderately active',height:165,weight:62,birthday:'1998-06-12',sex:'Female',name:'Neha',calories:2100,protein:130,carbs:260,fat:60,logged:false,deleted:false,xp:740,claimed:false,query:'',historyRange:'Week',selectedDay:21,selectedFood:'Harvest chicken bowl',notifications:{meals:true,water:true,quests:true,haptics:true},custom:null});render();toast('Prototype reset to the original sample day.');}else if(action==='nextScreen')go(ids[(ids.indexOf(state.screen)+1)%ids.length]);else if(action==='prevScreen')go(ids[(ids.indexOf(state.screen)-1+ids.length)%ids.length]);else if(action==='portionPlus'||action==='portionMinus'){state.portion=Math.max(.25,state.portion+(action==='portionPlus'?.25:-.25));render();}else if(action==='logFood'){addEntry(state.selectedFood,Math.round(foodNutrition()[0][0]*state.portion),state.meal,foodNutrition().slice(1).map(v=>Math.round(v[0]*state.portion)));}else if(action==='claim'){if(!state.claimed){state.claimed=true;state.xp+=10;go('reward');}else toast('You already collected this reward.');}else if(action==='toggle'){const key=target.dataset.key;state.notifications[key]=!state.notifications[key];render();}else if(action==='delete'){sheet('Remove this entry?','The food will be removed from this sample day. You can add it again anytime.',actionBtn('Remove entry','confirmDelete','danger')+actionBtn('Keep entry','closeSheet','secondary'));}else if(action==='confirmDelete'){const index=state.entries.findLastIndex(e=>e.name===state.selectedFood);if(index>=0)state.entries.splice(index,1);else if(state.selectedFood==='Harvest chicken bowl')state.deleted=true;else{document.querySelector('.sheet-overlay')?.remove();toast('This food is in your library. No matching new diary entry to remove.');return;}state.logged=state.entries.length>0;go('diary');toast('Entry removed from the sample diary.');}else if(action==='closeSheet')document.querySelector('.sheet-overlay')?.remove();else if(action==='waterGoal'){sheet('Your hydration target','Choose a personal target for the prototype. You can adjust it whenever you like.',`<form data-form="waterGoal">${field('Daily water target (ml)','waterGoal',state.waterGoal,'number')}<div class="mt20">${actionBtn('Save target','submitWater')}</div></form>`);}else if(action==='submitWater'){document.querySelector('[data-form="waterGoal"]')?.requestSubmit();}else if(action==='signout'){sheet('See you soon, '+esc(state.name)+'.','Sign out of this prototype session?',btn('Sign out','welcome')+actionBtn('Stay here','closeSheet','secondary'));}else if(action==='google'){sheet('Continue with Google','This is the account handoff preview. In the real app, Google will ask you to choose an account.',btn('Continue as Neha','about')+actionBtn('Cancel','closeSheet','secondary'));}else if(action==='retry') {go('home');toast('Back online — showing your sample day.');}else if(action==='upload'){go('scanning');toast('Previewing the analysis of the sample meal photo.');}else if(action==='remind'){go('settings');}else if(action==='unit'){sheet('Measurement units','Choose how measurements are displayed in the final app.',actionBtn('Metric · cm, kg, ml','metric')+actionBtn('Imperial · ft, lb, fl oz','imperial','secondary'));}else if(action==='metric'||action==='imperial'){document.querySelector('.sheet-overlay')?.remove();toast((action==='metric'?'Metric':'Imperial')+' preference previewed. This concept uses metric sample data.');}else if(action==='privacy'){sheet('Your data, your choice','Food logs, profile details, and photos should stay private. Production controls will include data export, photo retention, and account deletion.',actionBtn('Got it','closeSheet'));}else if(action==='deleteAccount'){sheet('Delete account','In the live app, this will require confirmation and permanently remove your account data. This preview does not contain a real account.',actionBtn('Back to settings','closeSheet','secondary'));}else if(action==='cameraPermission'){sheet('A photo is a good start','FitLens will request camera access only when you choose to take a meal photo.',btn('Preview camera','camera')+btn('Search food instead','search','secondary'));}else if(action==='checkin'){toast('Today’s check-in is complete. Claim your reward in Quests.');go('quests');}}
function sheet(title,copy,actions){document.querySelector('.sheet-overlay')?.remove();const el=document.createElement('div');el.className='sheet-overlay';el.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${title.replace(/<[^>]+>/g,'')}"><div class="sheet-grab"></div><div class="row between"><h2>${title}</h2><button class="round-btn" data-action="closeSheet" aria-label="Close dialog">${icon('close')}</button></div><p>${copy}</p><div class="stack mt24">${actions}</div></section>`;el.addEventListener('click',e=>{if(e.target===el)el.remove();});document.querySelector('.phone-shell .phone')?.append(el);el.querySelector('button')?.focus();}
function handleForm(type,data){if(type==='login')go('home');else if(type==='register'){state.name=data.get('name').trim().split(' ')[0]||'Neha';go('about');}else if(type==='reset'){sheet('Check your inbox','Password recovery confirmation preview. No email has been sent from this mockup.',btn('Back to sign in','login'));}else if(type==='about'){state.name=data.get('name').trim().split(' ')[0]||'Neha';state.activity=data.get('activity');for(const key of ['height','weight','birthday','sex'])state[key]=data.get(key);go('goal');}else if(type==='editProfile'){state.name=data.get('name').trim().split(' ')[0]||'Neha';state.activity=data.get('activity');for(const key of ['height','weight','birthday','sex'])state[key]=data.get(key);go('profile');toast('Profile updated in the prototype.');}else if(type==='targets'||type==='editGoals'){for(const key of ['calories','protein','carbs','fat'])state[key]=Number(data.get(key));go(type==='targets'?'ready':'profile');if(type==='editGoals')toast('Daily targets updated in the prototype.');}else if(type==='manual'){state.custom={name:data.get('foodName'),calories:Number(data.get('foodCalories'))};state.selectedFood=state.custom.name;state.meal=data.get('meal');state.portion=1;addEntry(state.custom.name,state.custom.calories,state.meal,['protein','carbs','fat'].map(k=>Number(data.get(k))));}else if(type==='waterGoal'){state.waterGoal=Math.max(250,Number(data.get('waterGoal')));render();toast('Hydration target updated.');}}
function authLogo(){return `<div class="auth-logo"><span class="brand-mark">${icon('spark')}</span>FitLens</div>`;}
function choice(key,value,label,subtitle,ic){return `<button class="option ${state[key]===value?'selected':''}" data-choice="${key}" data-value="${value}"><span class="option-icon">${icon(ic)}</span><span><h3>${label}</h3><p>${subtitle}</p></span><span class="check">${state[key]===value?icon('check'):''}</span></button>`;}
function targetFields(form){return `<form data-form="${form}"><div class="card mt20"><div class="row between"><span class="eyebrow lime">YOUR DAILY TARGETS</span>${icon('target','lime')}</div>${field('Energy · kcal','calories',state.calories,'number')}<div class="three">${field('Protein · g','protein',state.protein,'number')}${field('Carbs · g','carbs',state.carbs,'number')}${field('Fat · g','fat',state.fat,'number')}</div></div><p class="micro muted mt16">Sample targets for this concept. Your live plan will use your profile, and you can adjust it anytime.</p><button class="btn mt24" type="submit">${form==='targets'?'Looks good, let’s go':'Save my targets'} ${icon('arrow')}</button></form>`;}
function profileFields(form){return `<form data-form="${form}">${field('What should we call you?','name',state.name)}<div class="two">${field('Height · cm','height',state.height,'number')}${field('Weight · kg','weight',state.weight,'number')}</div>${field('Date of birth','birthday',state.birthday,'date')}${select('Sex used for energy estimate','sex',['Female','Male','Prefer to set my own targets'],state.sex)}${select('Your usual activity','activity',['Mostly sitting','Lightly active','Moderately active','Very active'],state.activity)}<p class="micro muted mt16">Your profile helps personalize your starting targets. You’re always in control of the numbers.</p><button class="btn mt24" type="submit">${form==='about'?'Continue':'Save profile'} ${icon('arrow')}</button></form>`;}
Object.assign(screens,{
welcome:()=>`${authLogo()}${art('ember','welcome-art','Meet Ember, your friendly flame companion')}<div class="center"><span class="chip">A LITTLE SPARK, EVERY DAY</span><h1 class="hero-copy mt20">Good food.<br>Better habits.<br><span class="lime">Your kind of fit.</span></h1><p class="intro-sub">Make sense of your meals.<br>Celebrate the small wins along the way.</p></div><div class="stack mt32">${btn('Find my spark','register','','arrow')}${btn('I already have an account','login','ghost')}</div><div class="legal">Your pace. Your progress. Always.</div>`,
login:()=>`${header('','welcome')}${authLogo()}<h1>Good to have<br>you back.</h1><p class="muted small mt12">Your next little win is waiting.</p><form data-form="login">${field('Email address','email','','email','you@example.com')}${field('Password','password','','password','Enter your password')}<div style="text-align:right;margin-top:10px"><button type="button" class="text-btn" data-go="reset">Forgot password?</button></div><button class="btn mt20" type="submit">Let’s pick up where you left off ${icon('arrow')}</button></form><div class="or">or</div>${actionBtn('Continue with Google','google','secondary')}<p class="small center muted mt24">New around here? <button class="text-btn" data-go="register">Create an account</button></p><p class="legal">Account flows are simulated in this design preview.</p>`,
register:()=>`${header('','welcome')}<h1>A fresh start.<br><span class="lime">A little spark.</span></h1><p class="muted small mt12">Let’s make feeling good a daily thing.</p><form data-form="register">${field('Your name','name','','text','What should we call you?')}${field('Email address','email','','email','you@example.com')}<label class="field">Create a password<input name="password" type="password" minlength="8" required placeholder="At least 8 characters"></label><button type="submit" class="btn mt24">Create my account ${icon('arrow')}</button></form><div class="or">or</div>${actionBtn('Continue with Google','google','secondary')}<p class="legal">By continuing, you agree to the <button class="text-btn" data-action="privacy">terms & privacy policy</button>.</p><p class="small center muted mt20">Already a member? <button class="text-btn" data-go="login">Sign in</button></p>`,
reset:()=>`${header('Reset password','login')}<div class="state-icon" style="margin-top:34px">${icon('mail')}</div><h1 class="center">Let’s get you<br>back in.</h1><p class="muted small center mt16">Enter your email and we’ll help you<br>reset your password.</p><form data-form="reset">${field('Email address','email','','email','you@example.com')}<button class="btn mt24" type="submit">Send reset link ${icon('arrow')}</button></form><p class="legal">Preview only. No email will be sent.</p>`,
about:()=>`${header('A little about you','register')}${steps(1)}<span class="eyebrow lime">STEP 01 / 03</span><h1 class="mt12">Start with you.</h1><p class="small muted mt12">A few details to make FitLens feel like yours.</p>${profileFields('about')}`,
goal:()=>`${header('Your direction','about')}${steps(2)}<span class="eyebrow lime">STEP 02 / 03</span><h1 class="mt12">What feels<br>right for you?</h1><p class="small muted mt12">Choose a direction. You can change<br>your mind whenever you want.</p><div class="stack mt32">${choice('goal','Build muscle','Build muscle','Fuel your strength and recovery.','dumbbell')}${choice('goal','Feel balanced','Feel balanced','Find a rhythm that works for you.','leaf')}${choice('goal','Manage weight','Manage weight','Make gradual, sustainable changes.','target')}</div><div class="card mt24"><div class="row">${icon('heart','orange')}<p class="small muted">Progress looks different on everyone.<br>This is your journey.</p></div></div><div class="mt32">${btn('Continue','targets','','arrow')}</div>`,
targets:()=>`${header('Your starting point','goal')}${steps(3)}<span class="eyebrow lime">STEP 03 / 03</span><h1 class="mt12">A plan that<br>moves with you.</h1><p class="small muted mt12">Your direction: <span class="lime">${state.goal}</span>.<br>Review your daily targets below.</p>${targetFields('targets')}`,
ready:()=>`${art('ember','success-art','Ember is ready to start your journey')}<div class="center">${chip('YOUR CHAPTER ONE','spark')}<h1 class="hero-copy mt20">You bring you.<br>We’ll bring<br><span class="lime">the spark.</span></h1><p class="intro-sub">Your plan is ready, ${esc(state.name)}.<br>Let’s start with one little meal.</p></div><div class="card mt24"><div class="row between"><span class="small muted">Your direction</span><strong class="small">${state.goal}</strong></div><div class="divider"></div><div class="row between"><span class="small muted">Daily energy target</span><strong>${state.calories.toLocaleString()} <span class="micro muted">kcal</span></strong></div></div><div class="stack mt24">${btn('Meet my dashboard','home','','arrow')}${btn('Review my targets','targets','ghost')}</div>`,
log:()=>`${header('Add a little fuel','home')}<h1>What’s on<br>your plate?</h1><p class="small muted mt12">Good food deserves a little credit.</p><div class="segmented mt24">${['Breakfast','Lunch','Dinner','Snack'].map(v=>`<button class="${state.meal===v?'selected':''}" data-choice="meal" data-value="${v}">${v}</button>`).join('')}</div><button class="scan-banner mt20" data-action="cameraPermission">${icon('scan')}<span><h3>Snap it. Check it. Log it.</h3><p>Start with a photo of your meal.</p></span></button><button class="search-box mt16" data-go="search" style="width:100%;text-align:left;color:#a5b891">${icon('search')}<span>Search foods, dishes, ingredients</span></button><div class="section-head"><h3>Your familiar favorites</h3>${chip('QUICK ADD')}</div>${foodRow('Harvest chicken bowl','1 bowl · 380 g','558','food','food',true)}${foodRow('Overnight oats','1 bowl · 250 g','426','sun')}${foodRow('Greek yogurt','1 cup · 170 g','120','food')}${foodRow('Banana','1 medium · 118 g','105','leaf')}<div class="mt24">${btn('Add a custom food','manual','ghost','plus')}</div><p class="micro center muted mt16">Nutrition is an estimate. You can always adjust it.</p>`,
search:()=>`${header('Find your food','log')}<div class="search-box">${icon('search')}<input id="foodSearch" value="${esc(state.query)}" placeholder="Try chicken, oats, or banana" aria-label="Search the sample food library" autocomplete="off"></div><div class="segmented mt16">${['Recent','Favorites','All foods'].map(v=>`<button data-choice="foodTab" data-value="${v}" class="${state.foodTab===v?'selected':''}">${v}</button>`).join('')}</div><div class="section-head"><h3>${state.foodTab==='All foods'?'Food library':state.foodTab==='Favorites'?'Your go-to foods':'Recently on your plate'}</h3><span class="micro muted">SAMPLE LIBRARY</span></div><div id="searchResults">${searchResults()}</div><div class="card mt24"><h3 style="font-size:13px">Something missing?</h3><p class="small muted mt8">Use the nutrition label to add your own.</p><div class="mt16">${btn('Create a custom food','manual','secondary','plus')}</div></div>`,
food:()=>`${header('Food details','search',`<button class="round-btn" data-action="delete" aria-label="Remove food entry">${icon('trash')}</button>`)}${art('meal-bowl','food-hero','Illustrative chicken and grain bowl')}<div class="row between mt20"><span class="eyebrow lime">${state.selectedFood==='Harvest chicken bowl'?'YOUR RECENT MEAL':'FOOD LIBRARY'}</span>${chip('EDITABLE','edit')}</div><h1 style="font-size:25px" class="mt12">${esc(state.selectedFood)}</h1><p class="small muted mt8">${state.selectedFood==='Harvest chicken bowl'?'Chicken, quinoa, avocado & greens':'Values shown for the sample serving'}</p><div class="card mt20"><div class="macro-detail">${foodNutrition().map(([n,l,c])=>`<div><strong class="${c}">${Math.round(n*state.portion)}</strong><span>${l}</span></div>`).join('')}</div></div><div class="section-head"><h3>Make it your portion</h3><span class="small muted">${Math.round(foodWeight()*state.portion)} g</span></div><div class="stepper"><button data-action="portionMinus" aria-label="Decrease serving">${icon('minus')}</button><span><strong>${state.portion}</strong> <span class="small muted">serving${state.portion===1?'':'s'}</span></span><button data-action="portionPlus" aria-label="Increase serving">${icon('plus')}</button></div><div class="segmented mt16">${['Breakfast','Lunch','Dinner','Snack'].map(v=>`<button class="${state.meal===v?'selected':''}" data-choice="meal" data-value="${v}">${v}</button>`).join('')}</div><div class="mt24">${actionBtn('Add to '+state.meal.toLowerCase(),'logFood','','plus')}</div><p class="micro muted center mt12">You can edit or remove this entry later.</p>`,
manual:()=>`${header('Create a food','log')}<h1>Your food.<br>Your details.</h1><p class="small muted mt12">Use the nutrition from the label.<br>All values below are for one serving.</p><form data-form="manual">${field('Food name','foodName','','text','e.g. Homemade dal')}${field('Serving size','serving','','text','e.g. 1 bowl · 200 g')}${field('Energy · kcal','foodCalories','','number','0')}<div class="three">${field('Protein · g','protein','','number','0')}${field('Carbs · g','carbs','','number','0')}${field('Fat · g','fat','','number','0')}</div>${select('Add to meal','meal',['Breakfast','Lunch','Dinner','Snack'],state.meal)}<button class="btn mt24" type="submit">Save food & log meal ${icon('plus')}</button></form>`,
camera:()=>`<div class="camera-screen">${header('Snap your meal','log',`<button class="round-btn" data-action="upload" aria-label="Preview gallery upload">${icon('upload')}</button>`)}${art('meal-bowl','camera-photo','Sample meal in the camera preview')}<div class="camera-frame"></div><span class="camera-tag">Keep the whole plate in the frame</span><div class="camera-bottom"><h3>One photo. A starting point.</h3><p class="small muted mt12">We’ll estimate the ingredients.<br>You’ll check the details.</p><button class="shutter" data-go="scanning" aria-label="Capture sample meal photo">${icon('camera')}</button><p class="micro muted mt16">Camera preview · sample photo</p><button class="text-btn mt16" data-go="search">Search for food instead</button></div></div>`,
scanning:()=>`${header('Getting the picture','camera')}<div class="scanning">${art('meal-bowl','food-hero','Meal being analyzed')}<span class="scan-line"></span></div><span class="chip mt20">${icon('spark')} AI PHOTO ESTIMATE</span><h1 class="mt20">A closer look<br>at your lunch.</h1><p class="small muted mt12">Finding the ingredients and a starting<br>estimate for your portion.</p><div class="mt16"><div class="step-list">${icon('check')} Photo received</div><div class="step-list">${icon('check')} Looking for familiar ingredients</div><div class="step-list">${icon('spark')} Putting your estimate together</div></div><div class="stack mt24">${btn('Preview the result','review','','arrow')}${btn('Preview a scan issue','scanError','ghost')}</div><p class="micro muted center mt12">Simulated analysis. No image leaves this preview.</p>`,
review:()=>`${header('A good starting point','camera')}${art('meal-bowl','food-hero','Photo of the scanned meal')}<div class="row between mt16">${chip('AI ESTIMATE','spark')}<span class="micro muted">Please check before adding</span></div><h1 style="font-size:25px" class="mt16">Looks like a<br>harvest chicken bowl.</h1><p class="small muted mt12">Here’s what we spotted. Portions, dressings,<br>and cooking oils can change the numbers.</p><div class="card mt16"><div class="row between"><strong>~${Math.round(558*state.portion)} kcal</strong><span class="small muted">${state.portion} serving</span></div><div class="divider"></div>${[['Grilled chicken','120 g'],['Quinoa','100 g'],['Avocado & vegetables','160 g']].map(([n,q])=>`<div class="row between mt12"><span class="small">${n}</span><span class="small muted">${q}</span></div>`).join('')}</div><div class="stack mt20">${actionBtn('Looks good · add to '+state.meal.toLowerCase(),'logFood','','check')}${btn('Adjust food & portion','food','secondary','edit')}${btn('Try another photo','camera','ghost')}</div>`,
logged:()=>`${art('achievement','success-art','A lime achievement token')}<div class="center"><span class="eyebrow lime">ANOTHER LITTLE WIN</span><h1 class="hero-copy mt16">Meal logged.<br>Look at you go.</h1><p class="intro-sub">A little more awareness.<br>A little more momentum.</p><div class="success-number">${state.lastXp?'+'+state.lastXp:'✓'} <span>${state.lastXp?'XP':'saved'}</span></div><p class="micro muted mt8">FOR SHOWING UP, NOT EATING LESS</p></div><div class="card mt24"><div class="row between"><strong class="small">${esc(state.lastEntry?.name||state.selectedFood)}</strong><span class="small lime">${state.lastEntry?.calories||Math.round(foodNutrition()[0][0]*state.portion)} kcal</span></div><p class="micro muted mt8">Added to ${(state.lastEntry?.meal||state.meal).toLowerCase()} · today</p><div class="divider"></div><div class="row between small"><span class="muted">Level 4 · Finding your rhythm</span><span>${state.xp} XP</span></div><div class="mt12">${progress(state.xp/1000*100)}</div></div><div class="stack mt24">${btn('Back to my day','home','','arrow')}${btn('See my quests','quests','ghost')}</div>`
});
const foods=[['Harvest chicken bowl','1 bowl · 380 g',558,'food',true],['Overnight oats','1 bowl · 250 g',426,'sun',false],['Greek yogurt','1 cup · 170 g',120,'food',false],['Banana','1 medium · 118 g',105,'leaf',false],['Grilled chicken breast','100 g',165,'food',false],['Avocado toast','1 slice · 130 g',245,'leaf',false],['Homemade dal','1 bowl · 200 g',220,'food',false],['Brown rice','1 cup · 195 g',216,'food',false]];
function searchResults(){const list=foods.filter((f,i)=>(state.foodTab!=='Favorites'||[0,2,3].includes(i))&&(state.foodTab!=='Recent'||i<5)&&f[0].toLowerCase().includes(state.query.toLowerCase()));return list.length?list.map(([n,d,c,ic,p])=>foodRow(n,d,c,ic,'food',p)).join(''):`<div class="center mt32"><div class="state-icon" style="margin:15px auto">${icon('search')}</div><h3>No food found just yet.</h3><p class="small muted mt12">Try a simpler name, or add it yourself.</p></div>`;}
function foodWeight(){return state.selectedFood==='Harvest chicken bowl'?380:state.selectedFood==='Banana'?118:state.selectedFood==='Greek yogurt'?170:100;}
function foodNutrition(){const map={'Harvest chicken bowl':[558,42,48,22],'Overnight oats':[426,21,58,13],'Greek yogurt':[120,17,6,3],'Banana':[105,1,27,0],'Grilled chicken breast':[165,31,0,4],'Avocado toast':[245,7,28,12],'Homemade dal':[220,12,32,5],'Brown rice':[216,5,45,2]};const nums=map[state.selectedFood]||[558,42,48,22];return nums.map((n,i)=>[n,['kcal','protein · g','carbs · g','fat · g'][i],['lime','orange','purple','blue'][i]]);}
document.addEventListener('input',e=>{if(e.target.id==='foodSearch'){state.query=e.target.value;document.getElementById('searchResults').innerHTML=searchResults();}});
function settingRow(label,ic,to,end=''){return `<button class="settings-row" data-go="${to}">${icon(ic)}<span>${label}</span><span class="end">${end}${icon('chevron')}</span></button>`;}
function toggleRow(label,ic,key){return `<button class="settings-row switch-row" data-action="toggle" data-key="${key}" role="switch" aria-checked="${state.notifications[key]}">${icon(ic)}<span>${label}</span><span class="end"><span class="toggle ${state.notifications[key]?'on':''}"></span></span></button>`;}
function weekChart(){const vals=state.historyRange==='Week'?[78,90,65,85,70,94,61]:state.historyRange==='Month'?[72,85,91,81]:[66,80,85,82,91,89];const labels=state.historyRange==='Week'?['T','W','T','F','S','S','M']:state.historyRange==='Month'?['W1','W2','W3','W4']:['Apr','May','Jun','Jul','Aug','Sep'];return `<div class="chart"><div class="chart-target"><span>Daily target</span></div>${vals.map((v,i)=>`<div class="bar ${i===vals.length-1?'current':''}" style="height:${v*0.8}%" title="${labels[i]}: ${Math.round(v*23)} kcal"></div>`).join('')}</div><div class="chart-labels">${labels.map(l=>`<span>${l}</span>`).join('')}</div>`;}
Object.assign(screens,{
diary:()=>`${header('Your food diary','home',`<button class="round-btn" data-go="log" aria-label="Add food">${icon('plus')}</button>`)}<div class="row between"><div><span class="eyebrow lime">${state.selectedDay===21?'TODAY':'SEPTEMBER '+state.selectedDay}</span><h1 class="mt8">A day of good food.</h1></div></div><div class="card mt20"><div class="row between"><span class="small muted">Energy logged</span><strong>${dayEnergy().toLocaleString()} <span class="micro muted">/ ${state.calories.toLocaleString()} kcal</span></strong></div><div class="mt12">${progress(dayEnergy()/state.calories*100)}</div></div><div class="section-head"><h3>${icon('sun','orange')} Breakfast</h3><span class="small muted">426 kcal</span></div>${foodRow('Overnight oats','1 bowl · 8:30 AM','426','sun')}${state.entries.filter(e=>e.meal==='Breakfast').map(e=>foodRow(esc(e.name),'Just added · '+e.portion+' serving',e.calories,'food')).join('')}<div class="section-head"><h3>${icon('sun','lime')} Lunch</h3><button class="text-btn" data-go="log">${icon('plus')} Add</button></div>${state.deleted?'<p class="small muted">No lunch entries. Add something you enjoyed.</p>':foodRow('Harvest chicken bowl','1 bowl · 1:15 PM','558','food','food',true)}${state.entries.filter(e=>e.meal==='Lunch').map(e=>foodRow(esc(e.name),'Just added · '+e.portion+' serving',e.calories,'food')).join('')}<div class="section-head"><h3>${icon('leaf','purple')} Snacks</h3><span class="small muted">300 kcal</span></div>${foodRow('Greek yogurt','1 cup · 4:00 PM','120','food')}${foodRow('Banana','With a handful of nuts','180','leaf')}${state.entries.filter(e=>e.meal==='Snack').map(e=>foodRow(esc(e.name),'Just added · '+e.portion+' serving',e.calories,'food')).join('')}<div class="section-head"><h3>${icon('moon','blue')} Dinner</h3><button class="text-btn" data-go="log">${icon('plus')} Add</button></div>${state.entries.filter(e=>e.meal==='Dinner').map(e=>foodRow(esc(e.name),'Just added · '+e.portion+' serving',e.calories,'food')).join('')}<button class="card card-click" data-go="log" style="border-style:dashed"><p class="small muted">Room for your next meal.</p><p class="small lime mt8">Add dinner ${icon('arrow')}</p></button><div class="mt24">${btn('See nutrition breakdown','nutrition','secondary','chart')}</div>`,
nutrition:()=>`${header('A closer look','home')}<span class="eyebrow orange">TODAY’S NUTRITION</span><h1 class="mt12">More than<br>just a number.</h1>${macros()}<div class="section-head"><h3>Your protein, broken down</h3><span class="small orange">86 g</span></div><div class="card">${[['Breakfast','21 g',24],['Lunch','42 g',49],['Snacks','23 g',27]].map(([n,v,p])=>`<div class="row between ${n==='Breakfast'?'':'mt20'}"><span class="small">${n}</span><strong class="small">${v}</strong></div><div class="mt8">${progress(p,'var(--orange)')}</div>`).join('')}<div class="divider"></div><p class="micro muted">From the foods logged so far. Tap a meal in your diary to see or edit its entries.</p></div><div class="section-head"><h3>The little nutrients</h3><span class="micro muted">AVAILABLE DATA</span></div><div class="card">${[['Fiber','18 g'],['Sugar','32 g'],['Sodium','1,140 mg'],['Potassium','2,180 mg']].map(([n,v],i)=>`<div class="row between ${i?'mt20':''}"><span class="small muted">${n}</span><strong class="small">${v}</strong></div>`).join('')}</div><p class="micro muted mt12">Some food sources don’t include every nutrient.</p><div class="mt20">${btn('Open my food diary','diary','secondary','book')}</div>`,
water:()=>`${header('A moment to hydrate','home',`<button class="round-btn" data-action="waterGoal" aria-label="Edit hydration target">${icon('settings')}</button>`)}<div class="center"><span class="eyebrow blue">SIP. PAUSE. REPEAT.</span><h1 class="mt12">Keep your flow.</h1><p class="small muted mt12">Little sips add up.</p></div><div class="water-big"><div class="water-fill" style="height:${Math.min(state.water/state.waterGoal*100,100)}%"></div><div class="water-big-label"><strong>${(state.water/1000).toFixed(2)}<span style="font-size:17px"> L</span></strong><span>of ${(state.waterGoal/1000).toFixed(1)} L today</span></div></div><p class="water-goal">${Math.round(state.water/state.waterGoal*100)}% of your personal target</p><div class="mt24">${actionBtn('Add a glass · 250 ml','water','','plus')}</div><div class="section-head"><h3>Today’s sips</h3><span class="small muted">${Math.floor(state.water/250)} glasses</span></div><div class="card">${[['Just now',state.water>1250?'250 ml':'No recent entry'],['12:45 PM','500 ml'],['10:00 AM','500 ml'],['8:30 AM','250 ml']].filter((x,i)=>i>0||state.water>1250).map(([t,v],i)=>`<div class="row between ${i?'mt16':''}"><span class="row small muted">${icon('water','blue')}${t}</span><strong class="small">${v}</strong></div>`).join('')}</div><button class="text-btn mt16" data-action="waterGoal" style="width:100%">Adjust my daily target</button>`,
history:()=>`<div class="row between"><div><span class="eyebrow lime">LOOK HOW FAR YOU’VE COME</span><h1 class="mt8">Your rhythm.</h1></div><button class="round-btn" data-go="streak" aria-label="View consistency calendar">${icon('calendar')}</button></div><div class="segmented mt24">${['Week','Month','6 months'].map(v=>`<button class="${state.historyRange===v?'selected':''}" data-choice="historyRange" data-value="${v}">${v}</button>`).join('')}</div><div class="card mt20"><div class="row between"><h3>Daily energy</h3><span class="micro muted">${state.historyRange==='Week'?'SEP 15–21':state.historyRange==='Month'?'SEPTEMBER':'APR–SEP'}</span></div><div class="mt16"><strong style="font:800 31px var(--display);letter-spacing:-1px">${state.historyRange==='Week'?'1,892':state.historyRange==='Month'?'1,946':'1,908'}</strong> <span class="small muted">kcal / day avg.</span></div>${weekChart()}</div><div class="two mt12"><div class="summary-stat"><span>Days checked in</span><strong>${state.historyRange==='Week'?'7 / 7':state.historyRange==='Month'?'21 / 21':'148 / 174'}</strong><small>Building a good rhythm</small></div><div class="summary-stat"><span>Average protein</span><strong>112 <span>g</span></strong><small>From your food logs</small></div></div><div class="card mt20"><div class="row">${icon('spark','lime')}<div><h3 style="font-size:14px">The habit is the highlight.</h3><p class="small muted mt8">You made time for yourself this week.<br>That counts for a lot.</p></div></div></div><div class="section-head"><h3>A look back</h3><span class="small muted">Your diary</span></div>${['Monday, Sep 21','Sunday, Sep 20','Saturday, Sep 19'].map((d,i)=>`<button class="settings-row" data-day="${21-i}">${icon('calendar')}<span>${d}</span><span class="end">${[1284,2030,1865][i]} kcal ${icon('chevron')}</span></button>`).join('')}`,
quests:()=>`<div class="row between"><div><span class="eyebrow lime">MAKE THE EVERYDAY A LITTLE FUN</span><h1 class="mt8">Little wins club.</h1></div><button class="round-btn" data-go="collection" aria-label="Your badge collection">${icon('trophy')}</button></div><button class="streak-card mt24" data-go="journey" style="min-height:143px;background:#28351e;border-color:#445d2e"><div><div class="eyebrow" style="color:var(--lime)">LEVEL 04 · FINDING YOUR RHYTHM</div><h3>Good things<br>are growing.</h3><p>${Math.max(0,1000-state.xp)} XP to your next chapter.</p></div>${art('ember','art','Ember celebrates your progress')}</button><div class="card mt12"><div class="row between small"><strong>Your spark</strong><span class="lime">${state.xp} / 1,000 XP</span></div><div class="mt12">${progress(state.xp/10)}</div><button class="text-btn mt12" data-go="journey">Explore your level journey ${icon('arrow')}</button></div><div class="section-head"><h3>Today’s quests</h3><span class="micro muted">RESETS TOMORROW</span></div><div class="quest-card"><span class="quest-icon">${icon('sun')}</span><div class="quest-body"><h3>A little hello to yourself</h3><p>Open your daily dashboard.</p>${progress(100)}</div><button class="quest-claim" data-action="claim" ${state.claimed?'disabled':''}>${state.claimed?'Claimed':'+10 XP'}</button></div><div class="quest-card"><span class="quest-icon">${icon('food')}</span><div class="quest-body"><h3>Make a meal memory</h3><p>Log your next meal.</p>${progress(state.logged?100:66)}</div><button class="text-btn" data-go="log">${state.logged?'Done ✓':'+25 XP'}</button></div><div class="quest-card"><span class="quest-icon" style="color:var(--blue)">${icon('water')}</span><div class="quest-body"><h3>A mindful sip</h3><p>Check in with your hydration.</p>${progress(state.water>1250?100:0,'var(--blue)')}</div><button class="text-btn" data-go="water">${state.hydrationRewarded?'Done ✓':'+15 XP'}</button></div><p class="micro muted center mt24">Do what feels right today. Quests are always optional.</p>`,
journey:()=>`${header('Your level journey','quests')}<span class="eyebrow lime">EVERY CHAPTER STARTS SMALL</span><h1 class="mt12">Keep your<br>spark going.</h1><p class="small muted mt12">Every check-in and meal memory<br>adds a little momentum.</p><div class="card mt24"><div class="row between"><span class="small">Level 4 · Finding your rhythm</span><strong class="lime small">${state.xp} XP</strong></div><div class="mt12">${progress(state.xp/10)}</div><p class="micro muted mt8">${Math.max(0,1000-state.xp)} XP to level 5</p></div><div class="mt32">${[['1','First spark','You took the first step.','done'],['2','Getting curious','A little more awareness.','done'],['3','Showing up','Consistency, your way.','done'],['4','Finding your rhythm','You are here. Keep being you.','current'],['5','In your element','Unlock the Momentum badge.','locked'],['6','A brighter chapter','More little wins ahead.','locked']].map(([n,t,d,c])=>`<div class="journey-node ${c}"><span class="node-num">${c==='done'?icon('check'):c==='locked'?icon('lock'):n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div>${btn('Explore my badge collection','collection','secondary','trophy')}`,
collection:()=>`${header('Your little trophies','quests')}<span class="eyebrow lime">COLLECT THE GOOD MOMENTS</span><h1 class="mt12">Proof you<br>showed up.</h1><p class="small muted mt12">Each badge tells a piece of your story.</p><div class="row between mt24"><h3>My collection</h3>${chip('3 / 6 UNLOCKED')}</div><div class="two mt16">${[['First spark','Your first check-in',false],['Meal explorer','10 meals remembered',false],['Seven little days','A week of check-ins',false],['Momentum','Reach level 5',true],['A mindful month','30 daily check-ins',true],['Good company','60 meal memories',true]].map(([n,d,l])=>`<button class="badge-card ${l?'locked':''}" data-action="badge" data-badge="${n}" data-description="${d}" data-locked="${l}">${art('achievement','','Achievement medallion')}<h3 style="color:var(--text)">${n}</h3><p>${l?'🔒 ':''}${d}</p></button>`).join('')}</div><p class="micro center muted mt24">A personal collection. No comparisons needed.</p>`,
reward:()=>`${header('A little celebration','quests')}${art('achievement','success-art','Your unlocked achievement token')}<div class="center"><span class="eyebrow lime">YOU EARNED THIS MOMENT</span><h1 class="hero-copy mt16">Small win.<br><span class="lime">Big spark.</span></h1><p class="intro-sub">A little hello to yourself.<br>Your daily check-in is complete.</p><div class="success-number">+10 <span>XP</span></div></div><div class="card mt24"><div class="row between small"><strong>Level 4 · Your spark</strong><span class="lime">${state.xp} XP</span></div><div class="mt12">${progress(state.xp/10)}</div><p class="micro muted mt12">Every little bit of consistency counts.</p></div><div class="stack mt24">${btn('Keep the good going','quests','','arrow')}${btn('View my collection','collection','ghost')}</div>`,
streak:()=>`${header('A week of showing up','home')}${art('ember','success-art','Ember, glowing warmly')}<div class="center"><span class="eyebrow orange">SEVEN LITTLE DAYS</span><h1 class="hero-copy mt12">Look at that<br><span style="color:var(--orange)">little fire.</span></h1><p class="small muted mt16">7 days of checking in with yourself.<br>Ember’s feeling the warmth.</p></div><div class="card mt24"><div class="row between"><h3>September</h3><span class="micro muted">2026</span></div><div class="calendar mt16">${['M','T','W','T','F','S','S'].map(d=>`<span class="calendar-head">${d}</span>`).join('')}${Array.from({length:28},(_,i)=>{const d=i;return `<span class="calday ${d<1||d>21?'empty':d===21?'today':d>=15?'done':''}">${d<1?'':d}</span>`;}).join('')}</div></div><div class="toast-inline mt16">Miss a day? Your earned XP stays yours. A new spark is always one check-in away.</div><div class="mt20">${btn('My daily quests','quests','','spark')}</div>`,
profile:()=>`<div class="row between"><h1>Your space.</h1><button class="round-btn" data-go="settings" aria-label="Open preferences">${icon('settings')}</button></div><div class="center mt32"><div class="avatar big">${esc(state.name[0]||'N')}</div><h2 class="mt16">${esc(state.name)}</h2><p class="small muted mt8">Finding your rhythm, one day at a time.</p><div class="mt12">${chip('LEVEL 4','spark')}</div></div><div class="two mt24"><button class="summary-stat" data-go="streak"><span>Current streak</span><strong class="orange">7 days</strong><small>Little check-ins, big energy</small></button><button class="summary-stat" data-go="collection"><span>Little trophies</span><strong>3 badges</strong><small>See your collection</small></button></div><div class="section-head"><h3>Your daily direction</h3><button class="text-btn" data-go="editGoals">Edit ${icon('edit')}</button></div><div class="card"><div class="row between"><span class="row small">${icon('dumbbell','lime')}${state.goal}</span><strong class="small">${state.calories.toLocaleString()} kcal</strong></div><div class="divider"></div><div class="three center">${[['Protein',state.protein,'orange'],['Carbs',state.carbs,'purple'],['Fat',state.fat,'blue']].map(([l,v,c])=>`<div><strong class="${c}">${v} g</strong><p class="micro muted mt8">${l}</p></div>`).join('')}</div></div><div class="mt16">${settingRow('Personal details','user','editProfile')}${settingRow('Daily targets','target','editGoals')}${settingRow('Preferences','settings','settings')}${settingRow('Your badge collection','trophy','collection')}</div><button class="settings-row" data-action="signout">${icon('logout')}Sign out</button>`,
editProfile:()=>`${header('Personal details','profile')}<h1>Always you.<br>Always evolving.</h1><p class="small muted mt12">Keep your details up to date.</p>${profileFields('editProfile')}`,
editGoals:()=>`${header('Your daily targets','profile')}<h1>A little room<br>to adjust.</h1><p class="small muted mt12">Your targets should work for your life.</p><div class="segmented mt20">${['Build muscle','Feel balanced','Manage weight'].map(v=>`<button data-choice="goal" data-value="${v}" class="${state.goal===v?'selected':''}">${v}</button>`).join('')}</div>${targetFields('editGoals')}`,
settings:()=>`${header('Make it yours','profile')}<h1>The little<br>preferences.</h1><p class="small muted mt12">Keep the useful things. Quiet the rest.</p><div class="section-head"><h3>Gentle reminders</h3><span class="micro muted">YOU’RE IN CONTROL</span></div>${toggleRow('Meal check-ins','food','meals')}${toggleRow('Hydration reminders','water','water')}${toggleRow('Quest & reward updates','spark','quests')}<div class="section-head"><h3>Your experience</h3></div>${toggleRow('Haptic feedback','bolt','haptics')}<button class="settings-row" data-action="unit">${icon('settings')}Measurement units<span class="end">Metric ${icon('chevron')}</span></button><div class="section-head"><h3>Your account</h3></div><button class="settings-row" data-action="privacy">${icon('shield')}Privacy & your data<span class="end">${icon('chevron')}</span></button>${settingRow('Change password','lock','reset')}<button class="settings-row" data-action="deleteAccount" style="color:#efa998">${icon('trash')}Delete account<span class="end">${icon('chevron')}</span></button><div class="card mt24"><p class="small muted">FitLens · A little spark, every day.</p><p class="micro muted mt8">Design concept 01 · Notification switches are simulated.</p></div>`,
notifications:()=>`${header('A few little nudges','home',`<button class="round-btn" data-go="settings" aria-label="Notification preferences">${icon('settings')}</button>`)}<h1>Good things<br>to know.</h1><p class="small muted mt12">A little encouragement, on your terms.</p><div class="section-head"><h3>Today</h3></div>${[['spark','lime','You made it a full week.','Seven check-ins. That’s a little rhythm worth celebrating.','10 minutes ago','streak'],['trophy','orange','A little win is waiting.','Your daily check-in quest is ready to claim.','1 hour ago','quests'],['water','blue','Time for a little pause?','Check in with your hydration when it feels right.','2 hours ago','water']].map(([ic,c,t,d,time,to])=>`<button class="notification" data-go="${to}" style="background:none;color:inherit;text-align:left;width:100%"><span class="quest-icon ${c}">${icon(ic)}</span><span><h3>${t}</h3><p>${d}</p><span class="micro muted">${time}</span></span></button>`).join('')}<div class="mt32">${btn('Choose my reminders','settings','ghost','settings')}</div>`,
empty:()=>`<div class="row between greeting"><div><span class="eyebrow muted">YOUR FIRST LITTLE CHAPTER</span><h1 class="mt8">Morning, ${esc(state.name)}.</h1></div><span class="avatar">${esc(state.name[0]||'N')}</span></div><div class="card mt24 center"><span class="small muted">Today’s energy</span><h1 style="font-size:48px" class="mt16">0 <span style="font-size:16px" class="muted">kcal</span></h1><p class="small muted mt8">Your day is a blank canvas.</p></div>${art('ember','success-art','Ember is here for your first meal')}<div class="center"><h2>Start with something<br>you enjoyed.</h2><p class="small muted mt16">A breakfast, a snack, a cup of something.<br>Your first meal memory starts here.</p></div><div class="mt24">${btn('Log my first food','log','','plus')}</div><p class="micro muted center mt16">No perfect days required.</p>`,
loading:()=>`<div class="row between"><div><div class="skeleton" style="width:130px;height:11px"></div><div class="skeleton mt12" style="width:190px;height:29px"></div></div><div class="skeleton" style="width:39px;height:39px;border-radius:50%"></div></div><div class="skeleton mt24" style="height:53px"></div><div class="skeleton mt20" style="height:232px;border-radius:24px"></div><div class="three mt12">${[1,2,3].map(()=>'<div class="skeleton" style="height:86px"></div>').join('')}</div><div class="skeleton mt16" style="height:107px;border-radius:20px"></div><div class="row center mt24" style="justify-content:center">${icon('refresh','lime')}<p class="small muted" role="status">Bringing your day together…</p></div><button class="text-btn mt24" data-go="home" style="width:100%">Preview loaded state</button>`,
offline:()=>`${header('Your day, on pause','home')}<div class="state-icon">${icon('wifi')}</div><div class="center"><h1>A little<br>connection hiccup.</h1><p class="small muted mt16">We can’t refresh your day right now.<br>Your last saved summary is below.</p></div><div class="error-banner mt24">Last updated at 8:42 AM. New entries and photo scans need a connection in this concept.</div><div class="card mt20"><div class="row between"><span class="small muted">Last saved energy</span><strong>426 kcal</strong></div><div class="divider"></div><div class="row between"><span class="small muted">Last saved hydration</span><strong>250 ml</strong></div></div><div class="stack mt24">${actionBtn('Try connecting again','retry','','refresh')}${btn('View my saved diary','diary','ghost')}</div>`,
scanError:()=>`${header('Let’s try another way','camera')}<div class="state-icon" style="background:#382a1e;color:var(--orange)">${icon('scan')}</div><div class="center"><h1>Not quite<br>the full picture.</h1><p class="small muted mt16">We couldn’t get a useful estimate.<br>A clearer photo or a quick search can help.</p></div><div class="card mt24"><h3 style="font-size:14px">For a better photo</h3><div class="step-list">${icon('sun')} Find a little natural light.</div><div class="step-list">${icon('camera')} Keep the whole plate in view.</div><div class="step-list" style="border:0">${icon('food')} Try one dish at a time.</div></div><div class="stack mt24">${btn('Try a new photo','camera','','camera')}${btn('Find food with search','search','secondary','search')}${btn('Enter it myself','manual','ghost')}</div>`
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open-screen]')){e.preventDefault();go(e.target.dataset.openScreen);}});
const hash=location.hash.slice(1);if(ids.includes(hash))state.screen=hash;
render();
